// This file is generated by AI.

// 语句配音配置面板 (配音卡操作台左侧)。
//
// 交互约定:
// * 参数编辑**永不禁用**: 一旦改动参数, 该配置即为"新配置", 不影响既有历史记录;
// * 「测试」入立即队列 (x4), 「生成」入普通队列 (x32);
// * 「应用」把选中历史项的音频落盘并改写 `-vocal=`;
//   「移除」只清除当前语句的 `-vocal=` (不删文件、不清历史);
// * 语音之外的参数 (文本) 随场景内容变化, 不随历史项回填。

import { Button, Input, Textarea } from '@fluentui/react-components';
import {
  ArrowSyncRegular,
  CheckmarkRegular,
  ChevronDownRegular,
  DeleteRegular,
  FlashRegular,
  MicRecordRegular,
  SettingsRegular,
} from '@fluentui/react-icons';
import { useEffect, useMemo, useState } from 'react';

import type { Character, SayLine } from '../commands/voice';
import { Select, toOptions } from '../components/Select';
import { voiceController } from './controller';
import { NumberInput } from './NumberInput';
import { VoiceReferenceDialog } from './VoiceReferenceDialog';
import { GENERATE_SAMPLE_STEPS, LANGUAGE_LABELS, PARAM_TICKS, randomSeed, type VoiceParams } from './types';

interface Props {
  cardId: string;
  dialogue: SayLine;
  characters: Character[];
  refreshToken: number;
  onChanged: () => void;
}

export function SentenceVoicePanel({ cardId, dialogue, characters, refreshToken, onChanged }: Props) {
  const [params, setParams] = useState<VoiceParams | null>(null);
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const [pickerOpen, setPickerOpen] = useState(false);
  const [busy, setBusy] = useState(false);
  const [message, setMessage] = useState<string | null>(null);

  // 切换语句 / 角色库变化时重建参数
  useEffect(() => {
    const next = voiceController.currentParams(cardId, dialogue);
    setParams(next);
    setMessage(null);
  }, [cardId, dialogue.line, dialogue.hash, refreshToken]);

  const card = voiceController.getCard(cardId);
  const selected = card?.selectedHistoryId
    ? (card.history.find((entry) => entry.id === card.selectedHistoryId) ?? null)
    : null;

  const character = useMemo(
    () => voiceController.characterById(params?.characterId ?? null),
    [params?.characterId, characters, refreshToken]
  );

  const match = card?.matches.get(dialogue.line);
  const matchHint = describeMatch(match?.reason);

  if (!params) return <div className="voice-sentence-panel" />;

  const update = (patch: Partial<VoiceParams>) => {
    setParams({ ...params, ...patch });
    // 参数一改, 视为新配置 -> 取消历史选中 (应用按钮随之禁用)
    setMessage(null);
    voiceController.selectHistory(cardId, null);
  };

  const isNewConfiguration = voiceController.isNewConfiguration(cardId, params);
  const canApply = Boolean(selected && selected.status === 'done' && selected.audioHash && !isNewConfiguration);
  const running = selected?.status === 'pending' || selected?.status === 'running';
  const hasVocal = Boolean(dialogue.vocal);

  const enqueue = (kind: 'test' | 'generate') => {
    if (!character || character.references.length === 0) {
      setMessage('请先为角色添加参考音频');
      return;
    }
    const reference =
      character.references.find((item) => item.hash === params.referenceHash) ?? character.references[0];
    const task = voiceController.enqueue(cardId, kind, dialogue, { ...params, referenceHash: reference.hash });
    if (task) {
      setMessage(kind === 'test' ? '已加入立即队列（测试 x4）' : '已加入普通队列（生成 x32）');
      onChanged();
    } else {
      setMessage('入队失败：找不到当前场景卡，请重新打开配音卡');
    }
  };

  const apply = async () => {
    if (!selected) return;
    setBusy(true);
    try {
      await voiceController.apply(cardId, selected.id);
      setMessage('已应用并更新 -vocal=');
      onChanged();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : String(error));
    } finally {
      setBusy(false);
    }
  };

  const remove = async () => {
    setBusy(true);
    try {
      await voiceController.remove(cardId);
      setMessage('已移除本句配音引用');
      onChanged();
    } catch (error) {
      setMessage(error instanceof Error ? error.message : String(error));
    } finally {
      setBusy(false);
    }
  };

  const cancel = () => {
    if (selected) {
      voiceController.cancel(selected.id);
      setMessage('已取消');
      onChanged();
    }
  };

  return (
    <div className="voice-sentence-panel">
      <div className="voice-row">
        <label className="voice-field voice-field-character">
          <span className="voice-label">角色</span>
          <Select
            value={params.characterId ?? ''}
            title={character ? `${character.name}${matchHint && !selected ? `（${matchHint}）` : ''}` : '未选择角色'}
            placeholder="未选择（点击选择角色）"
            options={characters.map((item) => ({
              value: item.id,
              label: `${item.name}${item.references.length === 0 ? '（无参考音频）' : ''}`,
            }))}
            onChange={(id) => {
              const next = voiceController.characterById(id || null);
              voiceController.assignCharacter(
                voiceController.getCard(cardId)?.scenePath ?? '',
                dialogue.speaker,
                id || null
              );
              update({
                characterId: id || null,
                referenceHash: next?.references[0]?.hash ?? null,
              });
            }}
          />
        </label>

        <label className="voice-field voice-field-language">
          <span className="voice-label">语言</span>
          <Select
            value={params.language}
            title="本条对话的合成语言"
            options={toOptions(LANGUAGE_LABELS)}
            onChange={(language) => update({ language })}
          />
        </label>
      </div>

      <label className="voice-field">
        <span className="voice-label">
          文本
          {dialogue.speaker === null && <span className="voice-label-tag">旁白</span>}
        </span>
        <Textarea
          className="voice-control voice-text"
          value={params.text}
          resize="vertical"
          onChange={(_, data) => update({ text: data.value })}
        />
      </label>

      <div className="voice-row">
        <label className="voice-field voice-field-reference">
          <span className="voice-label">参考音频</span>
          {/*
            参考音频用下拉直接选。
            `Select` 是就地展开的浮层, 但参考音频**需要看时长与文本**才能选, 选项里
            放不下这些信息, 因此这里点开即弹出选择对话框 (带搜索与试听), 比
            "只读文字 + 更换按钮"更直接: 那个按钮的文案让人以为要"更换文件"。
          */}
          <button
            type="button"
            className="select-trigger voice-reference-trigger"
            title={referenceLabel(character, params.referenceHash)}
            onClick={() => setPickerOpen(true)}
          >
            <span className="select-label">{referenceLabel(character, params.referenceHash)}</span>
            <ChevronDownRegular className="select-chevron" />
          </button>
        </label>

        <label className="voice-field voice-field-seed">
          <span className="voice-label">种子</span>
          <div className="voice-seed">
            <Input
              className="voice-control"
              value={String(params.seed)}
              onChange={(_, data) => {
                const parsed = Number.parseInt(data.value.replace(/[^0-9]/g, ''), 10);
                update({ seed: Number.isFinite(parsed) ? parsed : 0 });
              }}
            />
            <Button
              size="small"
              appearance="subtle"
              title="换一个随机种子"
              icon={<ArrowSyncRegular />}
              onClick={() => update({ seed: randomSeed() })}
            />
          </div>
        </label>
      </div>

      <div className="voice-row">
        <label className="voice-field">
          <span className="voice-label">温度</span>
          <NumberInput
            value={params.temperature}
            tick={PARAM_TICKS.temperature}
            onCommit={(temperature) => update({ temperature })}
          />
        </label>
        <label className="voice-field">
          <span className="voice-label">语速</span>
          <NumberInput
            value={params.speedFactor}
            tick={PARAM_TICKS.speedFactor}
            onCommit={(speedFactor) => update({ speedFactor })}
          />
        </label>
        {/* 高级设置的开关放在语速右边: 同一行更紧凑, 也少一行高度 */}
        <div className="voice-field voice-field-advanced">
          <span className="voice-label">&nbsp;</span>
          <Button
            appearance="subtle"
            size="small"
            icon={<SettingsRegular />}
            onClick={() => setAdvancedOpen((open) => !open)}
          >
            高级设置 {advancedOpen ? '▴' : '▾'}
          </Button>
        </div>
      </div>

      {advancedOpen && (
        <div className="voice-advanced-body">
          <div className="voice-row">
            <label className="voice-field">
              <span className="voice-label">topK</span>
              <NumberInput value={params.topK} tick={PARAM_TICKS.topK} integer onCommit={(topK) => update({ topK })} />
            </label>
            <label className="voice-field">
              <span className="voice-label">topP</span>
              <NumberInput value={params.topP} tick={PARAM_TICKS.topP} onCommit={(topP) => update({ topP })} />
            </label>
          </div>
          <div className="voice-row">
            <label className="voice-field">
              <span className="voice-label">重复惩罚</span>
              <NumberInput
                value={params.repetitionPenalty}
                tick={PARAM_TICKS.repetitionPenalty}
                onCommit={(repetitionPenalty) => update({ repetitionPenalty })}
              />
            </label>
          </div>
          <div className="voice-row">
            <label className="voice-field">
              <span className="voice-label">正式生成采样步数</span>
              <Select
                value={String(params.sampleSteps)}
                title="正式生成使用的采样步数"
                options={[4, 8, 16, 32].map((steps) => ({
                  value: String(steps),
                  label: `x${steps}${steps === GENERATE_SAMPLE_STEPS ? '（默认）' : ''}`,
                }))}
                onChange={(value) => update({ sampleSteps: Number.parseInt(value, 10) || GENERATE_SAMPLE_STEPS })}
              />
            </label>
          </div>
        </div>
      )}

      <div className="voice-actions">
        <Button appearance="secondary" icon={<FlashRegular />} disabled={Boolean(busy)} onClick={() => enqueue('test')}>
          测试 x4
        </Button>
        <Button
          appearance="primary"
          icon={<MicRecordRegular />}
          disabled={Boolean(busy)}
          onClick={() => enqueue('generate')}
        >
          生成 x{params.sampleSteps}
        </Button>
        <span className="voice-actions-spacer" />
        {running ? (
          <Button appearance="secondary" icon={<DeleteRegular />} onClick={cancel}>
            取消
          </Button>
        ) : (
          <Button
            appearance="secondary"
            title="清除当前语句的 -vocal=（不删除音频与历史）"
            icon={<DeleteRegular />}
            disabled={!hasVocal || Boolean(busy)}
            onClick={() => void remove()}
          >
            移除
          </Button>
        )}
        <Button
          appearance="primary"
          icon={<CheckmarkRegular />}
          disabled={!canApply || Boolean(busy)}
          onClick={() => void apply()}
        >
          应用
        </Button>
      </div>

      <div className="voice-status-line">
        {isNewConfiguration && !running && <span className="voice-hint-new">当前为新配置，尚未生成</span>}
        {message && <span className="voice-message">{message}</span>}
      </div>

      <VoiceReferenceDialog
        open={pickerOpen}
        character={character}
        selectedHash={params.referenceHash}
        onPick={(hash) => {
          update({ referenceHash: hash });
          setPickerOpen(false);
        }}
        onClose={() => setPickerOpen(false)}
        onCharactersChanged={onChanged}
      />
    </div>
  );
}

function referenceLabel(character: Character | null, hash: string | null): string {
  if (!character) return '未选择角色';
  if (character.references.length === 0) return '该角色暂无参考音频';
  const reference = character.references.find((item) => item.hash === hash) ?? character.references[0];
  const preview = reference.text.length > 14 ? `${reference.text.slice(0, 14)}…` : reference.text;
  return `${preview}（${reference.duration.toFixed(1)}s）`;
}

function describeMatch(reason: string | undefined): string {
  switch (reason) {
    case 'figureId':
      return '按立绘匹配';
    case 'name':
      return '按名称匹配';
    case 'narration':
      return '继承旁白';
    default:
      return '';
  }
}
